#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int v; struct Node *l, *r; } Node;
Node* new_node(int v) { Node* n = (Node*)malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }
void preorder(Node* root, int* first) { if (!root) return; if (!*first) putchar(' '); printf("%d", root->v); *first = 0; preorder(root->l, first); preorder(root->r, first); }
void inorder(Node* root, int* first) { if (!root) return; inorder(root->l, first); if (!*first) putchar(' '); printf("%d", root->v); *first = 0; inorder(root->r, first); }
void postorder(Node* root, int* first) { if (!root) return; postorder(root->l, first); postorder(root->r, first); if (!*first) putchar(' '); printf("%d", root->v); *first = 0; }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    if (n == 0 || a[0] == -1) return 0;
    Node* root = new_node(a[0]);
    Node* q[2000]; int head = 0, tail = 0; q[tail++] = root;
    int idx = 1;
    while (head < tail && idx < n) {
        Node* cur = q[head++];
        if (idx < n) { if (a[idx] != -1) { cur->l = new_node(a[idx]); q[tail++] = cur->l; } idx++; }
        if (idx < n) { if (a[idx] != -1) { cur->r = new_node(a[idx]); q[tail++] = cur->r; } idx++; }
    }
    int first = 1; printf("Inorder: "); inorder(root, &first); putchar('\n');
    first = 1; printf("Preorder: "); preorder(root, &first); putchar('\n');
    first = 1; printf("Postorder: "); postorder(root, &first); putchar('\n');
    free(a);
    return 0;
}

