import java.util.*;
public class Main {
    static class Node { int v; Node l, r; Node(int v) { this.v = v; } }
    static void preorder(Node root, List<String> res) { if (root == null) return; res.add(String.valueOf(root.v)); preorder(root.l, res); preorder(root.r, res); }
    static void inorder(Node root, List<String> res) { if (root == null) return; inorder(root.l, res); res.add(String.valueOf(root.v)); inorder(root.r, res); }
    static void postorder(Node root, List<String> res) { if (root == null) return; postorder(root.l, res); postorder(root.r, res); res.add(String.valueOf(root.v)); }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = sc.nextInt();
            if (n == 0 || a[0] == -1) return;
            Node root = new Node(a[0]);
            Queue<Node> q = new LinkedList<>(); q.add(root);
            int idx = 1;
            while (!q.isEmpty() && idx < n) {
                Node cur = q.poll();
                if (idx < n) { if (a[idx] != -1) { cur.l = new Node(a[idx]); q.add(cur.l); } idx++; }
                if (idx < n) { if (a[idx] != -1) { cur.r = new Node(a[idx]); q.add(cur.r); } idx++; }
            }
            List<String> ino = new ArrayList<>(), pre = new ArrayList<>(), post = new ArrayList<>();
            inorder(root, ino); preorder(root, pre); postorder(root, post);
            System.out.println("Inorder: " + String.join(" ", ino));
            System.out.println("Preorder: " + String.join(" ", pre));
            System.out.println("Postorder: " + String.join(" ", post));
        }
    }
}

