import sys
from collections import deque
def main():
    toks = [int(x) for x in sys.stdin.read().split()]
    if toks:
        n = toks[0]
        vals = toks[1:1+n]
        if not vals or vals[0] == -1: return
        class Node:
            def __init__(self, v): self.v = v; self.l = None; self.r = None
        root = Node(vals[0])
        q = deque([root]); idx = 1
        while q and idx < len(vals):
            cur = q.popleft()
            if idx < len(vals):
                if vals[idx] != -1:
                    cur.l = Node(vals[idx]); q.append(cur.l)
                idx += 1
            if idx < len(vals):
                if vals[idx] != -1:
                    cur.r = Node(vals[idx]); q.append(cur.r)
                idx += 1
        ino, pre, post = [], [], []
        def dfs(node):
            if not node: return
            pre.append(str(node.v)); dfs(node.l)
            ino.append(str(node.v)); dfs(node.r)
            post.append(str(node.v))
        dfs(root)
        print(f"Inorder: {' '.join(ino)}\nPreorder: {' '.join(pre)}\nPostorder: {' '.join(post)}")
if __name__ == "__main__": main()

