const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0], vals = toks.slice(1, 1 + n);
        if (vals.length === 0 || vals[0] === -1) return;
        class Node { constructor(v) { this.v = v; this.l = null; this.r = null; } }
        const root = new Node(vals[0]), q = [root];
        let idx = 1;
        while (q.length > 0 && idx < vals.length) {
            const cur = q.shift();
            if (idx < vals.length) {
                if (vals[idx] !== -1) { cur.l = new Node(vals[idx]); q.push(cur.l); }
                idx++;
            }
            if (idx < vals.length) {
                if (vals[idx] !== -1) { cur.r = new Node(vals[idx]); q.push(cur.r); }
                idx++;
            }
        }
        const ino = [], pre = [], post = [];
        function dfs(node) {
            if (!node) return;
            pre.push(node.v); dfs(node.l);
            ino.push(node.v); dfs(node.r);
            post.push(node.v);
        }
        dfs(root);
        console.log(`Inorder: ${ino.join(" ")}\nPreorder: ${pre.join(" ")}\nPostorder: ${post.join(" ")}`);
    }
}
main();

